    "top100_adv_ped_item1_desc": "Denke daran, dass Satzadverbien wie ‚ikke‘, ‚altid‘ und ‚aldrig‘ in Hauptsätzen normalerweise nach dem gebeugten Verb stehen, in Nebensätzen jedoch vor das Verb rücken.",
    "top100_adv_ped_item2_title": "Richtung auf ein Ziel vs. Ruhe am Ort",
    "top100_adv_ped_item2_desc": "Kurze Formen ohne -e (hjem, ind, ud, op) zeigen dynamische Bewegung auf ein Ziel zu, während lange Formen mit -e (hjemme, inde, ude, oppe) Ruhe und Stillstand an einem Ort ausdrücken.",
    "top100_adv_ped_item3_title": "Nuance, Grad und Modalpartikeln",
    "top100_adv_ped_item3_desc": "Gesprächswörter wie ‚jo‘, ‚da‘, ‚nok‘ und ‚vel‘ drücken geteiltes Wissen und Haltung im Gespräch aus, während Gradadverbien Eigenschaften von 0 % bis über 100 % abstufen.",
    "adv_f1_hero_title": "1. Ort: Richtung vs. Ruhe",
    "adv_f1_hero_desc": "Verstehe und meistere den klassischen dänischen Unterschied zwischen Bewegung auf ein Ziel zu (Kurzform) und Stillstand an einem Ort (Langform mit -e).",
    "adv_f1_rule_retning": "Richtung: Bewegung auf ein Ziel zu = KURZE FORM (hjem, ind, ud, op, ned, frem, hen)",
    "adv_f1_rule_hvile": "Ruhe: Stillstand am Ort = LANGE FORM mit -E (hjemme, inde, ude, oppe, nede, fremme, henne)",
    "adv_f2_hero_title": "2. Zeit & Häufigkeit",
    "adv_f2_hero_desc": "Lerne auszudrücken, wann etwas geschieht, wie oft es sich wiederholt (100 % bis 0 %), und meistere schwierige Zeitnuancen wie ‚allerede‘, ‚endnu‘ und ‚stadig‘.",
    "adv_f2_rule_frekvens": "Häufigkeit (Wie oft?): altid (100 %), ofte, tit, sommetider (50 %), sjældent, aldrig (0 %)",
    "adv_f2_rule_nuance": "Zeitablauf: nu, bagefter, før, allerede (früh), endnu (noch nicht), stadig (unverändert)",
    "adv_f3_hero_title": "3. Art und Weise (Die -t-Regel)",
    "adv_f3_hero_desc": "Wie läuft die Handlung ab? Verstehe die goldene Regel im Dänischen: Beschreibt das Wort ein Ding (Adjektiv) oder eine Handlung (Adverb)?",
    "adv_f3_rule_adjektiv": "Ding (Adjektiv): ‚Bussen er hurtig.‘ Beschreibt ein Substantiv.",
    "adv_f3_rule_adverbium": "Handlung (Adverb): ‚Bussen kører hurtigt.‘ Beschreibt das Verb mit -t.",
    "adv_f4_hero_title": "4. Grad & Intensität",
    "adv_f4_hero_desc": "Wie stark trifft es zu? Lerne, Stärke und Intensität von 0 % (slet ikke) bis über 100 % (alt for meget) zu steuern.",
    "adv_f4_rule_skala": "Die Skala: 0 % (slet ikke) ➔ 25 % (lidt) ➔ 60 % (ret/ganske) ➔ 80 % (meget) ➔ 100 % (helt) ➔ Über die Grenze (for meget).",
    "adv_f5_hero_title": "5. Die 5 magischen Gesprächswörter",
    "adv_f5_hero_desc": "Meistere die dänischen Modalpartikeln im Dialog: jo, da, nok, vel und vist. Lerne, wer was weiß und wie eine einzige Silbe den gesamten Ton verändert.",
    "adv_f5_rule_modal": "Modalpartikeln: jo (wir wissen es beide), da (Ermutigung/Selbstverständlichkeit), nok (Erwartung/Trost), vel (fragende Vermutung), vist (unsicheres Wissen).",
    "adv_f6_hero_title": "6. Gewissheit, Zweifel & Haltung",
    "adv_f6_hero_desc": "Meistere die Wahrscheinlichkeitsskala von 100 % Gewissheit (helt sikkert) über Vermutung (sandsynligvis) bis hin zu Zweifel (måske, næppe) und Ausschluss (umuligt).",
    "adv_f6_rule_sandsyn": "Wahrscheinlichkeit: 100 % (sikkert, selvfølgelig) ➔ 80 % (sandsynligvis, formentlig) ➔ 50 % (måske, muligvis) ➔ 10 % (næppe) ➔ 0 % (umuligt).",
    "adv_f7_hero_title": "7. Verbindung & Satzverknüpfer",
    "adv_f7_hero_desc": "Baue starke logische Brücken zwischen deinen Sätzen: Zeige Ursache und Wirkung (derfor, nemlig, altså), schaffe klaren Kontrast (alligevel, derimod) oder füge Informationen hinzu.",
    "adv_f7_rule_broer": "Logische Satzverknüpfer: Ursache (derfor, nemlig), Kontrast (alligevel, derimod), Hinzufügung (desuden, også), Alternative (ellers, i stedet).",
