    "adv_f1_rule_hvile": "Repouso: Permanência no local = FORMA LONGA com -E (hjemme, inde, ude, oppe, nede, fremme, henne)",
    "adv_f2_hero_title": "2. Tempo e frequência",
    "adv_f2_hero_desc": "Aprenda a expressar quando algo acontece, com que frequência se repete (de 100% a 0%) e domine nuances temporais difíceis como allerede, endnu e stadig.",
    "adv_f2_rule_frekvens": "Frequência (Com que frequência?): altid (100%), ofte, tit, sommetider (50%), sjældent, aldrig (0%)",
    "adv_f2_rule_nuance": "Linha do tempo: nu, bagefter, før, allerede (cedo), endnu (ainda não), stadig (inalterado)",
    "adv_f3_hero_title": "3. Modo (A regra do -t)",
    "adv_f3_hero_desc": "Como ocorre a ação? Entenda a regra de ouro em dinamarquês: a palavra descreve uma coisa (adjetivo) ou uma ação (advérbio)?",
    "adv_f3_rule_adjektiv": "Coisa (Adjetivo): 'Bussen er hurtig.' Descreve um substantivo.",
    "adv_f3_rule_adverbium": "Ação (Advérbio): 'Bussen kører hurtigt.' Descreve o verbo com -t.",
    "adv_f4_hero_title": "4. Grau e intensidade",
    "adv_f4_hero_desc": "Em que medida se aplica? Aprenda a controlar a força e a intensidade de 0% (slet ikke) a mais de 100% (alt for meget).",
    "adv_f4_rule_skala": "A escala: 0% (slet ikke) ➔ 25% (lidt) ➔ 60% (ret/ganske) ➔ 80% (meget) ➔ 100% (helt) ➔ Além do limite (for meget).",
    "adv_f5_hero_title": "5. As 5 palavras mágicas da conversação",
    "adv_f5_hero_desc": "Domine as partículas modais dinamarquesas no diálogo: jo, da, nok, vel e vist. Aprenda quem sabe o quê e como uma única sílaba altera todo o tom social.",
    "adv_f5_rule_modal": "Partículas modais: jo (nós dois sabemos), da (encorajamento/óbvio), nok (expectativa/conforto), vel (suposição interrogativa), vist (conhecimento incerto).",
    "adv_f6_hero_title": "6. Certeza, dúvida e atitude",
    "adv_f6_hero_desc": "Domine a escala de probabilidade de 100% de certeza (helt sikkert), passando pela suposição (sandsynligvis), até a dúvida (måske, næppe) e a impossibilidade (umuligt).",
    "adv_f6_rule_sandsyn": "Probabilidade: 100% (sikkert, selvfølgelig) ➔ 80% (sandsynligvis, formentlig) ➔ 50% (måske, muligvis) ➔ 10% (næppe) ➔ 0% (umuligt).",
    "adv_f7_hero_title": "7. Conexão e conectivos discursivos",
    "adv_f7_hero_desc": "Construa pontes lógicas sólidas entre suas frases: mostre causa e efeito (derfor, nemlig, altså), crie contraste marcante (alligevel, derimod) ou adicione informações.",
    "adv_f7_rule_broer": "Conectivos lógicos: Causa (derfor, nemlig), Contraste (alligevel, derimod), Adição (desuden, også), Alternativa (ellers, i stedet).",
