    "top100_adv_f3_title": "3. الكيفية والحال (قاعدة -t)",
    "top100_adv_f3_desc": "كيف يحدث الفعل؟ افهم القاعدة الذهبية: الشيء (en hurtig bil - صفة) مقابل الفعل (kører hurtigt - ظرف).",
    "top100_adv_f3_btn": "استكشف ظروف الكيفية ➔",
    "top100_adv_f4_badge": "🌡️ المجال 4 • 20 كلمة",
    "top100_adv_f4_title": "4. الدرجة والشدة",
    "top100_adv_f4_desc": "إلى أي مدى ينطبق ذلك؟ تدرّب على مقياس الشدة من 0% إلى أكثر من 100% (slet ikke, lidt, ret, meget, for varmt).",
    "top100_adv_f4_btn": "استكشف مقياس الشدة ➔",
    "top100_adv_f5_badge": "💬 المجال 5 • 18 كلمة",
    "top100_adv_f5_title": "5. الكلمات الحوارية السحرية الخمس",
    "top100_adv_f5_desc": "أدوات التضمين الحواري: jo, da, nok, vel, vist. تعلّم مَن يعرف ماذا، وكيف يغيّر مقطع صوتي واحد نبرة الحديث بالكامل.",
    "top100_adv_f5_btn": "أتقن أدوات المحادثة الصغيرة ➔",
    "top100_adv_f6_badge": "🎲 المجال 6 • 20 كلمة",
    "top100_adv_f6_title": "6. اليقين والشك والموقف",
    "top100_adv_f6_desc": "مقياس الاحتمالية من المؤكد تمامًا إلى المستحيل، بالإضافة إلى تقييم المتحدث: heldigvis, desværre, formentlig, umuligt.",
    "top100_adv_f6_btn": "استكشف الموقف والاحتمالية ➔",
    "top100_adv_f7_badge": "🔗 المجال 7 • 20 كلمة",
    "top100_adv_f7_title": "7. الربط وأدوات وصل النصوص",
    "top100_adv_f7_desc": "ابنِ ترابطًا منطقيًا بين الجمل والفقرات: derfor (السبب)، alligevel (التعارض)، nemlig (التوضيح/التعليل)، و ellers.",
    "top100_adv_f7_btn": "استكشف أدوات الربط ➔",
    "top100_adv_ped_title": "3 نصائح تعليمية لإتقان الظروف:",
    "top100_adv_ped_item1_title": "الموقع في الجملة (الظروف المركزية والقلب النحوي)",
    "top100_adv_ped_item1_desc": "تذكّر أن الظروف المركزية مثل 'ikke' و'altid' و'aldrig' تأتي عادةً بعد الفعل المصرّف في الجمل الرئيسية، لكنها تنتقل لتأتي قبل الفعل في الجمل الفرعية.",
    "top100_adv_ped_item2_title": "الاتجاه نحو الهدف مقابل السكون في المكان",
    "top100_adv_ped_item2_desc": "الصيغ القصيرة بدون -e (مثل hjem, ind, ud, op) تعبّر عن حركة ديناميكية نحو هدف، بينما الصيغ الطويلة مع -e (مثل hjemme, inde, ude, oppe) تعبّر عن السكون والاستقرار في مكان ما.",
    "top100_adv_ped_item3_title": "الدلالة الدقيقة والدرجة وأدوات التضمين",
    "top100_adv_ped_item3_desc": "تعبّر الكلمات الصغيرة مثل 'jo' و'da' و'nok' و'vel' عن المعرفة المشتركة والموقف في المحادثة، بينما تدرّج ظروف الدرجة الصفات من 0% إلى أكثر من 100%.",
    "adv_f1_hero_title": "1. المكان: الاتجاه مقابل السكون",
    "adv_f1_hero_desc": "افهم وأتقن الفارق الكلاسيكي في الدنماركية بين الحركة نحو هدف (صيغة قصيرة) والسكون في مكان واحد (صيغة طويلة مع -e).",
    "adv_f1_rule_retning": "الاتجاه: الحركة نحو هدف = صيغة قصيرة (hjem, ind, ud, op, ned, frem, hen)",
    "adv_f1_rule_hvile": "السكون: الاستقرار في المكان = صيغة طويلة مع -E (hjemme, inde, ude, oppe, nede, fremme, henne)",
    "adv_f2_hero_title": "2. الزمان والتكرار",
    "adv_f2_hero_desc": "تعلّم كيفية التعبير عن وقت حدوث الفعل، وكم مرة يتكرر (من 100% إلى 0%)، وأتقن الفروق الدقيقة للظروف الزمانية مثل allerede وendnu وstadig.",
    "adv_f2_rule_frekvens": "التكرار (كم مرة؟): altid (100%)، ofte، tit، sommetider (50%)، sjældent، aldrig (0%)",
    "adv_f2_rule_nuance": "التسلسل الزمني: nu (الآن)، bagefter (بعد ذلك)، før (من قبل)، allerede (مبكرًا / بالفعل)، endnu (ليس بعد)، stadig (ما زال مستمرًا)",
    "adv_f3_hero_title": "3. الكيفية والحال (قاعدة -t)",
    "adv_f3_hero_desc": "كيف يحدث الفعل؟ افهم القاعدة الذهبية في الدنماركية: هل تصف الكلمة شيئًا (صفة) أم تصف فعلًا/حدثًا (ظرف)؟",
    "adv_f3_rule_adjektiv": "الشيء (صفة): 'Bussen er hurtig.' تصف الاسم.",
    "adv_f3_rule_adverbium": "الفعل/الحدث (ظرف): 'Bussen kører hurtigt.' يصف الفعل بإضافة -t.",
    "adv_f4_hero_title": "4. الدرجة والشدة",
    "adv_f4_hero_desc": "إلى أي مدى ينطبق ذلك؟ تعلّم التحكم في القوة والشدة من 0% (slet ikke) إلى أكثر من 100% (alt for meget).",
    "adv_f4_rule_skala": "المقياس: 0% (slet ikke) ➔ 25% (lidt) ➔ 60% (ret/ganske) ➔ 80% (meget) ➔ 100% (helt) ➔ فوق الحد (for meget).",
    "adv_f5_hero_title": "5. الكلمات الحوارية السحرية الخمس",
    "adv_f5_hero_desc": "أتقن أدوات التضمين الدنماركية في الحوار: jo وda وnok وvel وvist. تعلّم مَن يعرف ماذا، وكيف يغيّر مقطع صوتي واحد النبرة بأكملها.",
    "adv_f5_rule_modal": "أدوات التضمين: jo (كلانا يعلم ذلك)، da (تشجيع/أمر بديهي)، nok (توقع/مواساة)، vel (تخمين واستفسار)، vist (معرفة غير مؤكدة).",
    "adv_f6_hero_title": "6. اليقين والشك والموقف",
    "adv_f6_hero_desc": "أتقن مقياس الاحتمالية من اليقين التام 100% (helt sikkert) مرورًا بالترجيح (sandsynligvis) إلى الشك (måske, næppe) والاستحالة (umuligt).",
    "adv_f6_rule_sandsyn": "الاحتمالية: 100% (sikkert, selvfølgelig) ➔ 80% (sandsynligvis, formentlig) ➔ 50% (måske, muligvis) ➔ 10% (næppe) ➔ 0% (umuligt).",
