    "adv_f3_hero_desc": "عمل کس طرح انجام پاتا ہے؟ ڈینش زبان کا سنہری قاعدہ سمجھیں: کیا لفظ کسی چیز کو بیان کر رہا ہے (صفت) یا کسی عمل کو (متعلق فعل)؟",
    "adv_f3_rule_adjektiv": "چیز (صفت): 'Bussen er hurtig.' یہ کسی اسم کو بیان کرتی ہے۔",
    "adv_f3_rule_adverbium": "عمل (متعلق فعل): 'Bussen kører hurtigt.' یہ فعل کو t- کے اضافے کے ساتھ بیان کرتا ہے۔",
    "adv_f4_hero_title": "4. درجہ اور شدت",
    "adv_f4_hero_desc": "یہ کس حد تک لاگو ہوتا ہے؟ 0% (slet ikke) سے لے کر 100% سے زیادہ (alt for meget) تک شدت کو کنٹرول کرنا سیکھیں۔",
    "adv_f4_rule_skala": "پیمانہ: 0% (slet ikke) ➔ 25% (lidt) ➔ 60% (ret/ganske) ➔ 80% (meget) ➔ 100% (helt) ➔ حد سے زیادہ (for meget)۔",
    "adv_f5_hero_title": "5. گفتگو کے 5 جادوئی چھوٹے الفاظ",
    "adv_f5_hero_desc": "گفتگو میں ڈینش کے انداز بدلنے والے چھوٹے الفاظ پر عبور حاصل کریں: jo، da، nok، vel اور vist۔ جانیں کہ کون کیا جانتا ہے اور کس طرح ایک ہی لفظ پورے لہجے کو بدل دیتا ہے۔",
    "adv_f5_rule_modal": "انداز بدلنے والے الفاظ: jo (ہم دونوں جانتے ہیں)، da (حوصلہ افزائی/ظاہر بات)، nok (توقع/تسلی)، vel (تصدیق طلب اندازہ)، vist (غیر یقینی معلومات)۔",
    "adv_f6_hero_title": "6. یقین، شک اور رویہ",
    "adv_f6_hero_desc": "100% یقین (helt sikkert) سے لے کر قیاس (sandsynligvis)، شک (måske, næppe) اور ناممکن (umuligt) تک امکان کے پیمانے پر عبور حاصل کریں۔",
    "adv_f6_rule_sandsyn": "امکان: 100% (sikkert, selvfølgelig) ➔ 80% (sandsynligvis, formentlig) ➔ 50% (måske, muligvis) ➔ 10% (næppe) ➔ 0% (umuligt)۔",
    "adv_f7_hero_title": "7. باہمی ربط اور جوڑنے والے الفاظ",
    "adv_f7_hero_desc": "اپنے جملوں کے درمیان مضبوط منطقی پل بنائیں: سبب اور نتیجہ دکھائیں (derfor, nemlig, altså)، واضح تضاد پیدا کریں (alligevel, derimod) یا اضافی معلومات شامل کریں۔",
    "adv_f7_rule_broer": "منطقی جوڑنے والے الفاظ: سبب (derfor, nemlig)، تضاد (alligevel, derimod)، اضافہ (desuden, også)، متبادل (ellers, i stedet)۔",
