    "top100_adv_f5_badge": "💬 Розділ 5 • 18 слів",
    "top100_adv_f5_title": "5. 5 магічних розмовних часток",
    "top100_adv_f5_desc": "Модальні частки в діалозі: jo, da, nok, vel, vist. Дізнайтеся, хто що знає, і як один склад змінює весь тон спілкування.",
    "top100_adv_f5_btn": "Опанувати розмовні частки ➔",
    "top100_adv_f6_badge": "🎲 Розділ 6 • 20 слів",
    "top100_adv_f6_title": "6. Впевненість, сумнів і ставлення",
    "top100_adv_f6_desc": "Шкала ймовірності від абсолютної впевненості до неможливості, а також оцінка мовця: heldigvis, desværre, formentlig, umuligt.",
    "top100_adv_f6_btn": "Дослідити ставлення та ймовірність ➔",
    "top100_adv_f7_badge": "🔗 Розділ 7 • 20 слів",
    "top100_adv_f7_title": "7. Зв'язність та текстові зв'язки",
    "top100_adv_f7_desc": "Створюйте логічний зв'язок між реченнями та абзацами: derfor (причина), alligevel (контраст), nemlig (обґрунтування) та ellers.",
    "top100_adv_f7_btn": "Дослідити текстові зв'язки ➔",
    "top100_adv_ped_title": "3 педагогічні поради для опанування прислівників:",
    "top100_adv_ped_item1_title": "Місце в реченні (центральні прислівники та інверсія)",
    "top100_adv_ped_item1_desc": "Пам'ятайте, що центральні прислівники, такі як 'ikke', 'altid' та 'aldrig', у головних реченнях зазвичай стоять після дієслова у відповідній формі, а в підрядних реченнях змінюють місце і стоять перед дієсловом.",
    "top100_adv_ped_item2_title": "Напрямок до мети проти Спокою на місці",
    "top100_adv_ped_item2_desc": "Короткі форми без закінчення -e (hjem, ind, ud, op) позначають динамічний рух до мети, тоді як довгі форми з закінченням -e (hjemme, inde, ude, oppe) виражають спокій та перебування на одному місці.",
    "top100_adv_ped_item3_title": "Нюанси, ступінь та модальні частки",
    "top100_adv_ped_item3_desc": "Розмовні частки, такі як 'jo', 'da', 'nok' та 'vel', виражають спільне знання та ставлення в розмові, тоді як прислівники ступеня градають властивості від 0% до понад 100%.",
    "adv_f1_hero_title": "1. Місце: Напрямок проти Спокою",
    "adv_f1_hero_desc": "Зрозумійте та опануйте класичну різницю в датській мові між рухом до мети (коротка форма) та перебуванням на одному місці (довга форма з -e).",
    "adv_f1_rule_retning": "Напрямок: Рух до мети = КОРОТКА ФОРМА (hjem, ind, ud, op, ned, frem, hen)",
    "adv_f1_rule_hvile": "Спокій: Перебування на місці = ДОВГА ФОРМА з -E (hjemme, inde, ude, oppe, nede, fremme, henne)",
    "adv_f2_hero_title": "2. Час і частотність",
    "adv_f2_hero_desc": "Навчіться виражати, коли щось відбувається, як часто повторюється (від 100% до 0%), та опануйте тонкі часові нюанси, такі як allerede, endnu і stadig.",
    "adv_f2_rule_frekvens": "Частотність (як часто?): altid (100%), ofte, tit, sommetider (50%), sjældent, aldrig (0%)",
    "adv_f2_rule_nuance": "Часовий перебіг: nu, bagefter, før, allerede (рано), endnu (ще не), stadig (досі / без змін)",
    "adv_f3_hero_title": "3. Спосіб дії (правило -t)",
    "adv_f3_hero_desc": "Як відбувається дія? Зрозумійте золоте правило датської мови: слово описує предмет (прикметник) чи дію (прислівник)?",
    "adv_f3_rule_adjektiv": "Предмет (Прикметник): 'Bussen er hurtig.' Описує іменник.",
    "adv_f3_rule_adverbium": "Дія (Прислівник): 'Bussen kører hurtigt.' Описує дієслово за допомогою -t.",
    "adv_f4_hero_title": "4. Ступінь та інтенсивність",
    "adv_f4_hero_desc": "Якою мірою? Навчіться регулювати силу та інтенсивність від 0% (slet ikke) до понад 100% (alt for meget).",
    "adv_f4_rule_skala": "Шкала: 0% (slet ikke) ➔ 25% (lidt) ➔ 60% (ret/ganske) ➔ 80% (meget) ➔ 100% (helt) ➔ Понад норму (for meget).",
    "adv_f5_hero_title": "5. 5 магічних розмовних часток",
    "adv_f5_hero_desc": "Опануйте датські модальні частки в діалозі: jo, da, nok, vel і vist. Дізнайтеся, хто що знає, і як один склад повністю змінює тон спілкування.",
    "adv_f5_rule_modal": "Модальні частки: jo (ми обоє це знаємо), da (підбадьорення/само собою), nok (очікування/розрада), vel (запитальне припущення), vist (невпевнене знання).",
    "adv_f6_hero_title": "6. Впевненість, сумнів і ставлення",
    "adv_f6_hero_desc": "Опануйте шкалу ймовірності від 100% впевненості (helt sikkert) через припущення (sandsynligvis) до сумніву (måske, næppe) та виключення (umuligt).",
    "adv_f6_rule_sandsyn": "Ймовірність: 100% (sikkert, selvfølgelig) ➔ 80% (sandsynligvis, formentlig) ➔ 50% (måske, muligvis) ➔ 10% (næppe) ➔ 0% (umuligt).",
    "adv_f7_hero_title": "7. Зв'язність та текстові зв'язки",
    "adv_f7_hero_desc": "Будуйте міцні логічні мости між реченнями: показуйте причину та наслідок (derfor, nemlig, altså), створюйте виразний контраст (alligevel, derimod) або додавайте інформацію.",
    "adv_f7_rule_broer": "Логічні зв'язки: причина (derfor, nemlig), контраст (alligevel, derimod), додавання (desuden, også), альтернатива (ellers, i stedet).",
