    "top100_adv_ped_item1_desc": "Hãy nhớ rằng các phó từ trung tâm như 'ikke', 'altid' và 'aldrig' thường đứng sau động từ chia trong mệnh đề chính, nhưng đổi vị trí và đứng trước động từ trong mệnh đề phụ.",
