    "top100_adv_ped_item2_desc": "Các dạng ngắn không có đuôi -e (hjem, ind, ud, op) thể hiện chuyển động linh hoạt hướng tới đích, trong khi các dạng dài có đuôi -e (hjemme, inde, ude, oppe) thể hiện sự yên vị và đứng yên tại một nơi.",
