    "adv_f1_rule_retning": "Phương hướng: Chuyển động tới mục tiêu = DẠNG NGẮN (hjem, ind, ud, op, ned, frem, hen)",
    "adv_f1_rule_hvile": "Đứng yên: Giữ nguyên vị trí = DẠNG DÀI có -E (hjemme, inde, ude, oppe, nede, fremme, henne)",
