    "adv_f2_rule_frekvens": "Tần suất (Bao lâu một lần?): altid (100%), ofte, tit, sommetider (50%), sjældent, aldrig (0%)",
    "adv_f2_rule_nuance": "Diễn tiến thời gian: nu, bagefter, før, allerede (sớm), endnu (chưa), stadig (vẫn tiếp diễn)",
