    "adv_f4_rule_skala": "Thang đo: 0% (slet ikke) ➔ 25% (lidt) ➔ 60% (ret/ganske) ➔ 80% (meget) ➔ 100% (helt) ➔ Vượt quá giới hạn (for meget).",
    "adv_f5_hero_title": "5. 5 tiểu từ hội thoại kỳ diệu",
    "adv_f5_hero_desc": "Làm chủ các tiểu từ tình thái Đan Mạch trong đối thoại: jo, da, nok, vel và vist. Tìm hiểu ai biết điều gì và làm thế nào một âm tiết duy nhất có thể thay đổi toàn bộ sắc thái giao tiếp.",
    "adv_f5_rule_modal": "Tiểu từ tình thái: jo (cả hai đều biết), da (khích lệ/đương nhiên), nok (kỳ vọng/an ủi), vel (phỏng đoán cầu thị), vist (biết nhưng chưa chắc).",
