    "adv_f6_rule_sandsyn": "Xác suất: 100% (sikkert, selvfølgelig) ➔ 80% (sandsynligvis, formentlig) ➔ 50% (måske, muligvis) ➔ 10% (næppe) ➔ 0% (umuligt).",
