    "top100_adv_ped_item1_title": "ตำแหน่งในประโยค (Centraladverbier และ Inversion การสลับลำดับคำ)",
    "top100_adv_ped_item1_desc": "จำไว้ว่าคำกริยาวิเศษณ์ส่วนกลาง เช่น 'ikke', 'altid' และ 'aldrig' มักจะอยู่หลังคำกริยาที่ผันในประโยคหลัก แต่จะเปลี่ยนตำแหน่งไปอยู่หน้าคำกริยาในอนุประโยค (ledsætninger)",
    "top100_adv_ped_item2_title": "ทิศทางสู่เป้าหมาย vs. การอยู่กับที่ ณ จุดนั้น",
    "top100_adv_ped_item2_desc": "รูปสั้นที่ไม่มี -e (hjem, ind, ud, op) แสดงการเคลื่อนที่ไปยังจุดหมายปลายทาง ในขณะที่รูปยาวที่มี -e (hjemme, inde, ude, oppe) แสดงความสงบและการอยู่กับที่ ณ ตำแหน่งหนึ่ง",
    "top100_adv_ped_item3_title": "เฉดความหมาย ระดับความเข้มข้น และคำเสริมน้ำเสียง",
    "top100_adv_ped_item3_desc": "คำสั้นๆ เช่น 'jo', 'da', 'nok' และ 'vel' ถ่ายทอดความรู้ร่วมและทัศนคติในการสนทนา ในขณะที่คำบอกระดับจะปรับระดับคุณสมบัติตั้งแต่ 0% ถึงมากกว่า 100%",
    "adv_f1_hero_title": "1. สถานที่: ทิศทางการเคลื่อนที่ vs. การอยู่กับที่",
    "adv_f1_hero_desc": "ในภาษาเดนมาร์ก เราแยกความแตกต่างอย่างชัดเจนระหว่างการเคลื่อนที่ไปยังสถานที่หนึ่ง กับการอยู่กับที่ ณ จุดนั้น คำสั้นที่ไม่มี -e แสดงทิศทางมุ่งสู่เป้าหมาย ส่วนคำยาวที่มี -e แสดงการอยู่กับที่",
    "adv_f1_rule_retning": "ทิศทาง: การเคลื่อนที่สู่เป้าหมาย = รูปสั้น (hjem, ind, ud, op, ned, frem, hen)",
    "adv_f1_rule_hvile": "การอยู่กับที่: การหยุดนิ่ง ณ ตำแหน่ง = รูปยาวที่มี -E (hjemme, inde, ude, oppe, nede, fremme, henne)",
    "adv_f2_hero_title": "2. เวลาและความถี่",
    "adv_f2_hero_desc": "เรียนรู้วิธีบอกว่าเหตุการณ์เกิดขึ้นเมื่อใด เกิดซ้ำบ่อยเพียงใด (100% ถึง 0%) ตลอดจนเชี่ยวชาญเฉดเวลาที่ซับซ้อน เช่น allerede, endnu และ stadig",
    "adv_f2_rule_frekvens": "ความถี่ (บ่อยแค่ไหน?): altid (100%), ofte, tit, sommetider (50%), sjældent, aldrig (0%)",
    "adv_f2_rule_nuance": "ลำดับเวลา: nu, bagefter, før, allerede (แต่เช้า/ก่อนกำหนด), endnu (ยัง...ไม่), stadig (ยังคงดำเนินอยู่)",
    "adv_f3_hero_title": "3. อาการและลักษณะ (กฎการเติม -t)",
    "adv_f3_hero_desc": "การกระทำดำเนินไปอย่างไร? เข้าใจกฎทองในภาษาเดนมาร์ก: คำนั้นกำลังขยายสิ่งของ (คำคุณศัพท์) หรือขยายการกระทำ (คำกริยาวิเศษณ์)?",
    "adv_f3_rule_adjektiv": "สิ่งของ (คำคุณศัพท์): 'Bussen er hurtig.' (รถเมล์คันนี้เร็ว) อธิบายคำนาม",
    "adv_f3_rule_adverbium": "การกระทำ (คำกริยาวิเศษณ์): 'Bussen kører hurtigt.' (รถเมล์วิ่งอย่างรวดเร็ว) อธิบายคำกริยาโดยเติม -t",
    "adv_f4_hero_title": "4. ระดับและความเข้มข้น",
    "adv_f4_hero_desc": "มีผลระดับไหน? เรียนรู้วิธีควบคุมน้ำหนักและความเข้มข้นตั้งแต่ 0% (slet ikke) ไปจนถึงเกิน 100% (alt for meget)",
    "adv_f4_rule_skala": "สเกล: 0% (slet ikke) ➔ 25% (lidt) ➔ 60% (ret/ganske) ➔ 80% (meget) ➔ 100% (helt) ➔ เกินขีดจำกัด (for meget)",
    "adv_f5_hero_title": "5. คำเสริมน้ำเสียงมหัศจรรย์ 5 คำ",
    "adv_f5_hero_desc": "เชี่ยวชาญคำเสริมน้ำเสียงในบทสนทนาภาษาเดนมาร์ก: jo, da, nok, vel และ vist เรียนรู้ว่าใครรู้อะไร และพยางค์เดียวเปลี่ยนน้ำเสียงทางสังคมทั้งหมดได้อย่างไร",
    "adv_f5_rule_modal": "คำเสริมน้ำเสียง: jo (เราทั้งคู่ต่างรู้ดี), da (ให้กำลังใจ/เป็นเรื่องแน่นอน), nok (ความคาดหวัง/ปลอบใจ), vel (สันนิษฐานเพื่อขอการยืนยัน), vist (ความรู้ที่ยังไม่แน่ใจ)",
    "adv_f6_hero_title": "6. ความมั่นใจ ความสงสัย และทัศนคติ",
    "adv_f6_hero_desc": "เชี่ยวชาญสเกลความน่าจะเป็นตั้งแต่ความมั่นใจ 100% (helt sikkert) ผ่านการสันนิษฐาน (sandsynligvis) ไปจนถึงความสงสัย (måske, næppe) และการปฏิเสธอย่างสิ้นเชิง (umuligt)",
    "adv_f6_rule_sandsyn": "ความน่าจะเป็น: 100% (sikkert, selvfølgelig) ➔ 80% (sandsynligvis, formentlig) ➔ 50% (måske, muligvis) ➔ 10% (næppe) ➔ 0% (umuligt)",
