    "adv_f7_rule_broer": "คำเชื่อมโยงเชิงตรรกะ: สาเหตุ (derfor, nemlig), ความขัดแย้ง (alligevel, derimod), การเพิ่มเติม (desuden, også), ทางเลือกอื่น (ellers, i stedet)",
