    "top100_adv_ped_item1_title": "वाक्यमा स्थान (केन्द्रीय क्रियाविशेषण र विपरित क्रम/Inversion)",
    "top100_adv_ped_item1_desc": "याद राख्नुहोस् कि 'ikke', 'altid' र 'aldrig' जस्ता केन्द्रीय क्रियाविशेषणहरू सामान्यतया मुख्य उपवाक्यहरूमा क्रियाको पछाडि आउँछन्, तर अधीनस्थ उपवाक्यहरू (ledsætninger) मा स्थान परिवर्तन गरी क्रियाभन्दा अगाडि आउँछन्।",
