/**
 * Helper to retrieve translated meaning and example sentence for an adverb in the active language.
 * Falls back to English if the active language is not available, then Danish.
 */
export function getAdverbWordTranslation(wordKey, field = null, lang = null) {
  let targetLang = lang;
  if (!targetLang && typeof window !== 'undefined') {
    const hashSegments = window.location.hash.split('/');
    if (hashSegments.length > 1 && hashSegments[1]) {
      targetLang = hashSegments[1];
    } else {
      targetLang = localStorage.getItem('appLang') || 'da';
    }
  }
  if (!targetLang) targetLang = 'da';

  let entry = null;

  if (field) {
    entry = adverbierWordTranslations[`f${field}_${wordKey}`];
  }
  if (!entry) {
    entry = adverbierWordTranslations[wordKey];
  }
  if (!entry) {
    // Search by baseWord
    const foundKey = Object.keys(adverbierWordTranslations).find(k => {
      const item = adverbierWordTranslations[k];
      return item.id === wordKey || item.baseWord === wordKey;
    });
    if (foundKey) entry = adverbierWordTranslations[foundKey];
  }

  if (!entry) return null;

  const trans = entry[targetLang] 
    || (targetLang !== 'da' ? entry['en'] : null) 
    || entry['da'];

  return trans;
}
